-- calories per serving on recipes (filled by the meal bot from USDA FoodData Central / product labels)
alter table public.recipes add column if not exists calories_per_serving integer check (calories_per_serving is null or calories_per_serving between 1 and 5000),
  add column if not exists calories_approx boolean not null default false,
  add column if not exists calories_basis text check (calories_basis is null or length(calories_basis) <= 600),
  add column if not exists calories_note text check (calories_note is null or length(calories_note) <= 300),
  add column if not exists calories_checked_at timestamptz;

update public.recipes set calories_per_serving=583, calories_approx=true, calories_basis='Batch of 2 plates ~1,165 kcal: 0.67 lb chicken thighs, 0.67 cup dry rice, 1 broccoli crown, brown sugar, soy sauce, oil, cornstarch, ketchup ÷ 2 plates. USDA FoodData Central standard values.', calories_note='Approximate: broccoli crown weight estimated at ~0.75 lb.', calories_checked_at=now() where id::text like '77e1ee67%' and household_id='733cd381-babb-490c-863f-ee16ee942ad4';
